def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def components(grid, color=None):
    """All 4-connected same-color components as cell lists (optionally one color only)."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    comps = []
    for i in range(h):
        for j in range(w):
            if seen[i][j] or (color is not None and grid[i][j] != color):
                continue
            c = grid[i][j]
            if color is None and c == background(grid):
                continue
            q = deque([(i, j)]); seen[i][j] = True; cells = []
            while q:
                y, x = q.popleft(); cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == c:
                        seen[ny][nx] = True; q.append((ny, nx))
            comps.append(cells)
    return comps

def bbox(cells):
    """(top, left, bottom, right) of a list of (row, col) cells."""
    ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
    return min(ys), min(xs), max(ys), max(xs)

def fill_interiors(grid, fill_fn):
    """Fill each non-background component's bounding-box interior with fill_fn(height, width)."""
    bg = background(grid)
    out = [row[:] for row in grid]
    for cells in components(grid):
        t, l, b, r = bbox(cells)
        f = fill_fn(b - t + 1, r - l + 1)
        for y in range(t + 1, b):
            for x in range(l + 1, r):
                if out[y][x] == bg:
                    out[y][x] = f
    return out

def parity_fill(h, w):
    """7 if both dimensions are odd, else 2."""
    return 7 if h % 2 == 1 and w % 2 == 1 else 2
